import {quantityHierarchy,groupHeadings} from './levels.js';
import {readWorkbook} from './workbook.js';
import {mappedImport,importFields} from './mapped-import.js';
import {escapeHtml as e} from './print-pack.js';
export function setupMappedImport(api){
 const $=id=>document.getElementById(id);
 document.body.insertAdjacentHTML('beforeend',`<input id="mappedFile" type="file" accept=".xlsx" hidden><dialog id="mappedDialog"><div class="dialog-head"><div><h2>엑셀 열 지정 가져오기</h2><p>수량·내역·단가표의 열을 지정합니다. 저장된 계산값을 우선 사용하고, 저장값이 없는 지원 수식은 참조 셀로 계산합니다. 미계산·불일치는 확인 대상으로 남깁니다.</p></div><button class="icon-btn" data-close="mappedDialog" aria-label="닫기">×</button></div><div class="mapped-body"><div class="work-fields"><label>시트<select id="mappedSheet" aria-label="가져올 시트"></select></label><label>종류<select id="mappedMode" aria-label="가져올 종류"><option value="quantity">수량산출서</option><option value="estimate">설계내역서</option><option value="rate">단가 DB</option></select></label><label>시작 행<input id="mappedStart" type="number" min="1" value="2"></label><label>종료 행<input id="mappedEnd" type="number" min="1"></label><label>단가 구분<select id="mappedCategory" aria-label="가져올 단가 구분">${['자재','노임','장비','일위대가','단가산출','표준시장단가'].map(k=>'<option>'+k+'</option>').join('')}</select></label><label>합계 단가만 있을 때<select id="mappedTarget" aria-label="합계 단가 계상 비목"><option value="material">재료비에 계상</option><option value="labor">노무비에 계상</option><option value="expense">경비에 계상</option></select></label><label>내역 추가 방식<select id="mappedAppend" aria-label="내역 추가 방식"><option value="append">현재 내역 뒤에 추가</option><option value="replace">현재 내역 교체</option></select></label></div><details><summary>원본 시트 미리보기 (앞 12행)</summary><div id="mappedRaw" class="work-table"></div></details><div class="work-fields" id="mappedColumns"></div><button class="button" id="mappedPreview">가져올 내용 검토</button><div id="mappedResult" class="work-table"></div></div><div class="dialog-actions"><span id="mappedMessage" role="status"></span><button id="mappedApply" class="button primary" disabled>검토한 내용 가져오기</button></div></dialog>`);
 let sheets=[],file='',pending=null,projectStamp='';
 const sheet=()=>sheets[Number($('mappedSheet').value)];
 const options=()=>({file,mode:$('mappedMode').value,start:Number($('mappedStart').value),end:Number($('mappedEnd').value),category:$('mappedCategory').value,target:$('mappedTarget').value});
 const mapping=()=>Object.fromEntries([...$('mappedColumns').querySelectorAll('[data-map]')].map(el=>[el.dataset.map,el.value]));
 const stamp=()=>JSON.stringify([$('mappedSheet').value,options(),mapping(),$('mappedAppend').value]);
 const message=text=>$('mappedMessage').textContent=text;
 function renderSheet(){const s=sheet();if(!s)return;const cols=[...new Set(s.rows.flatMap(r=>Object.keys(r.cells)))].sort((a,b)=>a.length-b.length||a.localeCompare(b));
  $('mappedEnd').value=Math.max(1,...s.rows.map(r=>r.index));$('mappedStart').value=2;
  $('mappedColumns').innerHTML=Object.entries(importFields).map(([key,label])=>`<label>${label}<select data-map="${key}" aria-label="${label} 열"><option value="">지정 안 함</option>${cols.map(c=>'<option>'+c+'</option>').join('')}</select></label>`).join('');
  const names={name:['품명','품목','공종명'],spec:['규격'],unit:['단위'],qty:['수량'],group:['공종','구분'],level:['레벨','L'],code:['코드'],labor:['노무단가','노무비단가'],material:['재료단가','재료비단가'],expense:['경비단가'],other:['기타단가'],total:['합계단가','단가'],amount:['합계금액','금액']};
  const header=s.rows.slice(0,15).find(r=>Object.values(r.cells).some(c=>names.name.includes(String(c.value).replace(/\s/g,''))));
  if(header){$('mappedStart').value=header.index+1;for(const [key,labels] of Object.entries(names)){const col=Object.entries(header.cells).find(([,c])=>labels.includes(String(c.value).replace(/\s/g,'')))?.[0];if(col)$('mappedColumns').querySelector(`[data-map="${key}"]`).value=col;}}
  $('mappedRaw').innerHTML='<table><thead><tr><th>행</th>'+cols.slice(0,35).map(c=>'<th>'+e(c)+'</th>').join('')+'</tr></thead><tbody>'+s.rows.slice(0,12).map(r=>'<tr><td>'+r.index+'</td>'+cols.slice(0,35).map(c=>'<td>'+e(r.cells[c]?.value??'')+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
  pending=null;$('mappedApply').disabled=true;$('mappedResult').innerHTML='';message('열과 가져올 행 범위를 확인하세요.');
 }
 $('mappedSheet').onchange=renderSheet;
 $('mappedFile').onchange=async event=>{try{const f=event.target.files[0];if(!f)return;if(f.size>80*1024*1024)throw Error('엑셀 파일은 80MB 이하로 선택하세요.');file=f.name;sheets=await readWorkbook(await f.arrayBuffer(),{fileName:f.name});if(!sheets.length)throw Error('읽을 수 있는 시트가 없습니다.');projectStamp=JSON.stringify(api.getProject());$('mappedSheet').innerHTML=sheets.map((s,i)=>`<option value="${i}">${e(s.name)}</option>`).join('');renderSheet();$('mappedDialog').showModal();}catch(err){api.toast(err.message);}finally{$('mappedFile').value='';}};
 $('mappedPreview').onclick=()=>{try{pending={...mappedImport(sheet(),mapping(),options()),stamp:stamp()};const items=options().mode==='rate'?pending.rates:pending.rows;$('mappedResult').innerHTML='<table><thead><tr><th>공종 / 구분</th><th>품명</th><th>규격</th><th>단위</th><th>수량 / 단가</th><th>확인</th></tr></thead><tbody>'+items.slice(0,200).map(r=>'<tr><td>'+e(r.group||r.category)+'</td><td>'+e(r.name)+'</td><td>'+e(r.spec)+'</td><td>'+e(r.unit)+'</td><td class="number">'+e(r.qty??r.total??'미확정')+'</td><td>'+e(r.note||'')+'</td></tr>').join('')+'</tbody></table>'+pending.issues.map(x=>'<p>'+x.row+'행 '+e(x.name)+' — '+e(x.reason)+'</p>').join('');message(items.length+'건 · 확인/보류 '+pending.issues.length+'건'+(items.length>200?' · 앞 200건 표시':''));$('mappedApply').disabled=!items.length;}catch(err){pending=null;$('mappedApply').disabled=true;message(err.message);}};
 $('mappedApply').onclick=async()=>{try{if(!pending||pending.stamp!==stamp())throw Error('설정이 바뀌었습니다. 다시 검토하세요.');if(JSON.stringify(api.getProject())!==projectStamp)throw Error('현재 내역이 바뀌었습니다. 파일을 다시 열어주세요.');$('mappedApply').disabled=true;
  if(options().mode==='rate'){const id=crypto.randomUUID(),name=file+' · '+sheet().name;const items=pending.rates.map(r=>({...r,library:id,source:name}));await api.addLibrary({id,name,version:'Excel',items,stats:[{category:options().category,count:items.length}],details:[],tables:[],excelLibrary:true,importMapping:mapping()});}
  else{const next=structuredClone(api.getProject());if($('mappedAppend').value==='replace'){if(next.lines.length&&!confirm('기존 내역을 가져온 내역으로 교체할까요?')){$('mappedApply').disabled=false;return;}next.lines=pending.rows;}else{const incoming=options().mode==='quantity'&&next.lines.some(l=>l.level)&&!pending.rows.some(l=>l.level)?groupHeadings({lines:pending.rows}).lines:pending.rows;next.lines.push(...incoming);}if(options().mode==='quantity'){const arranged=quantityHierarchy(next);next.lines=arranged.lines;}next.quantityFile=file;next.ratesReviewed=false;api.replaceProject(next);}
  $('mappedDialog').close();api.toast('엑셀 내용을 가져왔습니다. 확인 표시가 있는 항목을 검토하세요.');
 }catch(err){message(err.message);$('mappedApply').disabled=false;}};
 return {open:()=>$('mappedFile').click()};
}
